(async () => { const A = window.__CITY_APP, scene = A.scene, sun = A.lightingSystem.sunLight;
 const meas = async (n = 100) => { const ts = []; for (let i = 0; i < n + 15; i++) { await new Promise((r) => requestAnimationFrame(r)); ts.push(performance.now()); } const d = []; for (let i = 16; i < ts.length; i++) d.push(ts[i] - ts[i - 1]); d.sort((a, b) => a - b); return +d[d.length >> 1].toFixed(2); };
 const R = {}; R.base = await meas();
 sun.castShadow = false; R.noSunShadow = await meas(); sun.castShadow = true;
 const prox = scene.getObjectByName('ShadowProxies'); if (prox) { prox.visible = false; R.noStandIns = await meas(); prox.visible = true; }
 const mass = [], was = []; scene.traverse((o) => { if (/^MassingBuildings_/.test(o.name) && o.visible) { mass.push(o); was.push(o.castShadow); } });
 mass.forEach((o) => { o.visible = false; }); R.massingMeshesHidden = await meas(); mass.forEach((o) => { o.visible = true; });
 const bld = scene.getObjectByName('CityBuildings'); if (bld) { bld.visible = false; R.allBuildingsHidden = await meas(); bld.visible = true; }
 R.base2 = await meas(); R.massingVisible = mass.length; return R; })()

